"""Small read-only adapters with bounded responses and explicit projections."""

from __future__ import annotations

import json
from datetime import date
from typing import Any, Literal

import httpx

from .config import Settings, Upstream

ArrService = Literal["sonarr", "radarr", "lidarr"]
TautulliMediaType = Literal["movie", "episode", "track"]


class UpstreamError(RuntimeError):
    """A sanitized upstream failure suitable for returning from an MCP tool."""


class ParameterError(ValueError):
    """A tool argument is outside the broker's safe bounds."""


async def _bounded_body(response: httpx.Response, maximum: int) -> bytes:
    content_length = response.headers.get("content-length")
    if content_length:
        try:
            if int(content_length) > maximum:
                raise UpstreamError(
                    "upstream response exceeds the configured size limit"
                )
        except ValueError as exc:
            raise UpstreamError("upstream returned an invalid response length") from exc
    chunks: list[bytes] = []
    size = 0
    async for chunk in response.aiter_bytes():
        size += len(chunk)
        if size > maximum:
            raise UpstreamError("upstream response exceeds the configured size limit")
        chunks.append(chunk)
    return b"".join(chunks)


class MediaClient:
    """HTTP client for the four allow-listed upstream APIs."""

    def __init__(
        self, settings: Settings, transport: httpx.AsyncBaseTransport | None = None
    ):
        self.settings = settings
        self._client = httpx.AsyncClient(
            follow_redirects=False,
            timeout=httpx.Timeout(settings.timeout_seconds),
            verify=True,
            transport=transport,
        )

    async def aclose(self) -> None:
        await self._client.aclose()

    async def _json(
        self, upstream: Upstream, path: str, *, params: dict[str, Any] | None = None
    ) -> Any:
        headers = {"X-Api-Key": upstream.api_key}
        try:
            async with self._client.stream(
                "GET", f"{upstream.base_url}{path}", headers=headers, params=params
            ) as response:
                if 300 <= response.status_code < 400:
                    raise UpstreamError("upstream redirects are not accepted")
                if response.status_code >= 400:
                    raise UpstreamError(
                        f"upstream returned HTTP {response.status_code}"
                    )
                body = await _bounded_body(response, self.settings.max_response_bytes)
        except UpstreamError:
            raise
        except (httpx.HTTPError, OSError) as exc:
            raise UpstreamError("upstream request failed") from exc
        try:
            return json.loads(body)
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise UpstreamError("upstream returned invalid JSON") from exc

    def _arr(self, service: ArrService) -> Upstream:
        return self.settings.upstreams[service]

    async def inventory(
        self, service: ArrService, page: int, page_size: int, search: str | None = None
    ) -> dict[str, Any]:
        _validate_page(page, page_size)
        endpoint = {
            "sonarr": "/api/v3/series",
            "radarr": "/api/v3/movie",
            "lidarr": "/api/v1/artist",
        }[service]
        payload = await self._json(self._arr(service), endpoint)
        if not isinstance(payload, list):
            raise UpstreamError("upstream returned an unexpected inventory")
        if len(payload) > self.settings.max_items:
            raise UpstreamError("upstream inventory exceeds the configured item limit")
        query = search.strip().casefold() if search else None
        projected = [
            _project_arr_item(item) for item in payload if isinstance(item, dict)
        ]
        if query:
            projected = [
                item
                for item in projected
                if query in str(item.get("title", "")).casefold()
            ]
        start = (page - 1) * page_size
        items = projected[start : start + page_size]
        return {
            "service": service,
            "items": items,
            "pagination": {
                "page": page,
                "page_size": page_size,
                "returned_count": len(items),
                "total_count": len(projected),
                "has_more": start + len(items) < len(projected),
                "upstream_paginated": False,
                "upstream_truncated": False,
            },
        }

    async def quality_profiles(self, service: ArrService) -> dict[str, Any]:
        payload = await self._json(
            self._arr(service),
            "/api/" + self._arr(service).api_version + "/qualityprofile",
        )
        if not isinstance(payload, list) or len(payload) > self.settings.max_items:
            raise UpstreamError(
                "upstream returned an unexpected quality profile response"
            )
        items = []
        for item in payload:
            if isinstance(item, dict):
                items.append(
                    {
                        "id": item.get("id"),
                        "name": item.get("name"),
                        "upgrade_allowed": item.get("upgradeAllowed"),
                        "cutoff": item.get("cutoff"),
                    }
                )
        return {"service": service, "items": items, "upstream_truncated": False}

    async def root_folders(self, service: ArrService) -> dict[str, Any]:
        payload = await self._json(
            self._arr(service), "/api/" + self._arr(service).api_version + "/rootfolder"
        )
        if not isinstance(payload, list) or len(payload) > self.settings.max_items:
            raise UpstreamError("upstream returned an unexpected root folder response")
        items = []
        for item in payload:
            if isinstance(item, dict):
                items.append(
                    {
                        "id": item.get("id"),
                        "path": item.get("path"),
                        "accessible": item.get("accessible"),
                        "free_space_bytes": item.get("freeSpace"),
                        "total_space_bytes": item.get("totalSpace"),
                    }
                )
        return {"service": service, "items": items, "upstream_truncated": False}

    async def history(
        self,
        media_type: TautulliMediaType,
        start_date: str,
        end_date: str,
        page: int,
        page_size: int,
    ) -> dict[str, Any]:
        _validate_page(page, page_size)
        start, end = _validate_dates(start_date, end_date)
        offset = (page - 1) * page_size
        upstream = self.settings.upstreams["tautulli"]
        payload = await self._json(
            upstream,
            "/api/v2",
            params={
                "cmd": "get_history",
                "apikey": upstream.api_key,
                "start": offset,
                "length": page_size,
                "media_type": media_type,
                "start_date": start.isoformat(),
                "end_date": end.isoformat(),
            },
        )
        if not isinstance(payload, dict):
            raise UpstreamError("upstream returned an unexpected history response")
        response_data = payload.get("response", {}).get("data", {})
        rows = response_data.get("data", []) if isinstance(response_data, dict) else []
        if not isinstance(rows, list) or len(rows) > page_size:
            raise UpstreamError("upstream returned an unexpected history page")
        items = [
            _project_history_item(row, media_type)
            for row in rows
            if isinstance(row, dict) and row.get("media_type", media_type) == media_type
        ]
        total = (
            response_data.get("recordsFiltered")
            if isinstance(response_data, dict)
            else None
        )
        if not isinstance(total, int) or total < offset + len(items):
            total = None
        return {
            "media_type": media_type,
            "start_date": start.isoformat(),
            "end_date": end.isoformat(),
            "items": items,
            "pagination": {
                "page": page,
                "page_size": page_size,
                "returned_count": len(items),
                "upstream_total_count": total,
                "has_more": (total is not None and offset + len(items) < total)
                or len(items) == page_size,
                "upstream_paginated": True,
                "upstream_truncated": total is None and len(items) == page_size,
            },
        }


def _validate_page(page: int, page_size: int) -> None:
    if not isinstance(page, int) or not 1 <= page <= 100_000:
        raise ParameterError("page must be between 1 and 100000")
    if not isinstance(page_size, int) or not 1 <= page_size <= 100:
        raise ParameterError("page_size must be between 1 and 100")


def _validate_dates(start_value: str, end_value: str) -> tuple[date, date]:
    try:
        start = date.fromisoformat(start_value)
        end = date.fromisoformat(end_value)
    except (TypeError, ValueError) as exc:
        raise ParameterError("dates must use YYYY-MM-DD") from exc
    if end < start or (end - start).days > 31:
        raise ParameterError("date range must be non-negative and at most 31 days")
    return start, end


def _project_arr_item(item: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": item.get("id"),
        "title": item.get("title") or item.get("artistName"),
        "year": item.get("year"),
        "status": item.get("status"),
        "monitored": item.get("monitored"),
        "quality_profile_id": item.get("qualityProfileId"),
        "root_folder_path": item.get("rootFolderPath"),
    }


def _project_history_item(
    item: dict[str, Any], media_type: TautulliMediaType
) -> dict[str, Any]:
    # Deliberately omit users, rating/device/IP identifiers, and all unknown fields.
    return {
        "media_type": media_type,
        "title": item.get("title"),
        "parent_title": item.get("parent_title"),
        "grandparent_title": item.get("grandparent_title"),
        "played_at": item.get("started") or item.get("started_at"),
        "duration_seconds": item.get("duration"),
        "completed": item.get("watched_status") == "watched"
        or item.get("watched_status") == 1,
    }

"""MCP server exposing only bounded, read-only media inventory queries."""

from __future__ import annotations

import asyncio
import secrets
from typing import Any

from mcp.server.fastmcp import FastMCP
from mcp.server.transport_security import TransportSecuritySettings
from starlette.types import Receive, Scope, Send

from .adapters import (
    ArrService,
    MediaClient,
    ParameterError,
    TautulliMediaType,
    UpstreamError,
)
from .config import Settings, load_settings


class BearerMiddleware:
    """Require the configured bearer on every HTTP route, including MCP discovery."""

    def __init__(self, app: Any, token: str):
        self.app = app
        self.token = token

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] != "http":
            await self.app(scope, receive, send)
            return
        headers = dict(scope.get("headers", []))
        authorization = headers.get(b"authorization", b"").decode("latin-1")
        scheme, separator, candidate = authorization.partition(" ")
        valid = (
            separator == " "
            and scheme.casefold() == "bearer"
            and bool(candidate)
            and len(candidate) <= 4096
            and secrets.compare_digest(candidate, self.token)
        )
        if not valid:
            body = b'{"error":"authentication required"}'
            await send(
                {
                    "type": "http.response.start",
                    "status": 401,
                    "headers": [
                        (b"content-type", b"application/json"),
                        (b"content-length", str(len(body)).encode()),
                    ],
                }
            )
            await send({"type": "http.response.body", "body": body})
            return
        await self.app(scope, receive, send)


def create_mcp(settings: Settings, client: MediaClient | None = None) -> FastMCP:
    """Construct an SDK-backed MCP server; no tool accepts arbitrary upstream input."""
    owned_client = client or MediaClient(settings)
    mcp = FastMCP(
        name="media-broker",
        instructions="Read-only, projected media-service inventory and household playback history.",
        host=settings.bind_host,
        port=settings.port,
        streamable_http_path="/mcp",
        stateless_http=True,
        transport_security=TransportSecuritySettings(
            enable_dns_rebinding_protection=True,
            allowed_hosts=list(settings.allowed_hosts),
            allowed_origins=list(settings.allowed_origins),
        ),
    )

    @mcp.tool()
    async def arr_library_inventory(
        service: ArrService,
        page: int = 1,
        page_size: int = 50,
        search: str | None = None,
    ) -> dict[str, Any]:
        """Return a bounded page of Sonarr, Radarr, or Lidarr library inventory."""
        return await _safe(
            lambda: owned_client.inventory(service, page, page_size, search)
        )

    @mcp.tool()
    async def arr_quality_profiles(service: ArrService) -> dict[str, Any]:
        """Return projected quality-profile summaries for one Arr service."""
        return await _safe(lambda: owned_client.quality_profiles(service))

    @mcp.tool()
    async def arr_root_folders(service: ArrService) -> dict[str, Any]:
        """Return projected root-folder summaries for one Arr service."""
        return await _safe(lambda: owned_client.root_folders(service))

    @mcp.tool()
    async def tautulli_play_history(
        media_type: TautulliMediaType,
        start_date: str,
        end_date: str,
        page: int = 1,
        page_size: int = 50,
    ) -> dict[str, Any]:
        """Return sanitized movie, episode, or track playback history for <=31 days."""
        return await _safe(
            lambda: owned_client.history(
                media_type, start_date, end_date, page, page_size
            )
        )

    return mcp


async def _safe(operation: Any) -> dict[str, Any]:
    try:
        return await operation()
    except ParameterError as exc:
        # Tool callers receive validation without implementation details.
        return {"error": str(exc)}
    except UpstreamError as exc:
        return {"error": str(exc)}
    except (KeyError, TypeError):
        return {"error": "invalid service or parameters"}
    except Exception:
        # Do not let SDK/client internals or upstream payloads reach the caller.
        return {"error": "operation failed"}


class ClosingMiddleware:
    """Close the shared upstream client after the server lifespan ends."""

    def __init__(self, app: Any, client: MediaClient):
        self.app = app
        self.client = client

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] != "lifespan":
            await self.app(scope, receive, send)
            return
        try:
            await self.app(scope, receive, send)
        finally:
            await self.client.aclose()


def build_app(settings: Settings) -> Any:
    """Build the authenticated Streamable HTTP ASGI application for tests or uvicorn."""
    client = MediaClient(settings)
    mcp_app = create_mcp(settings, client).streamable_http_app()
    return ClosingMiddleware(BearerMiddleware(mcp_app, settings.bearer_token), client)


def main() -> None:
    import uvicorn

    settings = load_settings()
    app = build_app(settings)
    asyncio.run(
        uvicorn.Server(
            uvicorn.Config(app, host=settings.bind_host, port=settings.port)
        ).serve()
    )

"""Configuration and secret-file handling for the media broker."""

from __future__ import annotations

import os
from dataclasses import dataclass, field
from pathlib import Path
from urllib.parse import urlsplit


class ConfigError(ValueError):
    """Raised when required broker configuration is absent or unsafe."""


def _required(name: str) -> str:
    value = os.environ.get(name, "").strip()
