from __future__ import annotations

import argparse
import os
import pathlib
import re
import tempfile
from urllib.parse import urlsplit

import yaml

MARKER = "ansible-managed-hermes-media-broker-v1\n"
TOKEN_KEY = "MEDIA_BROKER_TOKEN"
TOKEN_REFERENCE = "${MEDIA_BROKER_TOKEN}"
TOKEN_LINE = re.compile(r"^\s*(?:export\s+)?MEDIA_BROKER_TOKEN\s*=")
TOOLS = [
    "arr_library_inventory",
    "arr_quality_profiles",
    "arr_root_folders",
    "tautulli_play_history",
]


def fail(message: str) -> None:
    raise SystemExit(message)


def read_yaml(path: pathlib.Path) -> dict:
    if not path.exists():
        return {}
    try:
        with path.open(encoding="utf-8") as stream:
            value = yaml.safe_load(stream)
    except (OSError, yaml.YAMLError):
        fail("invalid Hermes YAML")
    if value is None:
        return {}
    if not isinstance(value, dict):
        fail("invalid Hermes YAML")
    return value


def is_owned(marker: pathlib.Path) -> bool:
    try:
        return marker.read_text(encoding="utf-8") == MARKER
    except (FileNotFoundError, OSError):
        return False


def managed_entry(url: str) -> dict:
    return {
        "url": url,
        "headers": {"Authorization": f"Bearer {TOKEN_REFERENCE}"},
        "include_tools": TOOLS,
        "sampling": False,
        "elicitation": False,
        "resources": False,
        "prompts": False,
    }


def reconcile_yaml(path: pathlib.Path, enabled: bool, url: str, takeover: bool, owned: bool) -> tuple[dict, bool]:
    before = read_yaml(path)
    servers = before.get("mcp_servers")
    if servers is not None and not isinstance(servers, dict):
        fail("invalid Hermes mcp_servers configuration")
    servers = dict(servers or {})
    existing = servers.get("media_broker")
    if existing is not None and not isinstance(existing, dict):
        fail("invalid Hermes media broker configuration")

    if enabled:
        if existing is not None and not owned and not takeover:
            fail("unowned Hermes media broker configuration")
        servers["media_broker"] = managed_entry(url)
        before["mcp_servers"] = servers
    elif owned and existing is not None:
        del servers["media_broker"]
        before["mcp_servers"] = servers
    return before, before != read_yaml(path)


def reconcile_env(path: pathlib.Path, enabled: bool, token: str, owned: bool) -> tuple[str, bool]:
    if not path.exists():
        lines: list[str] = []
    else:
        try:
            lines = path.read_text(encoding="utf-8").splitlines(keepends=True)
        except OSError:
            fail("unable to read Hermes environment")
    matches = [line for line in lines if TOKEN_LINE.match(line)]
    if matches and not owned:
        fail("unowned Hermes media token")
    kept = [line for line in lines if not TOKEN_LINE.match(line)]
    if enabled:
        kept.append(f"{TOKEN_KEY}={token}\n")
    return "".join(kept), "".join(kept) != "".join(lines)


def atomic_write(path: pathlib.Path, content: str) -> None:
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent, text=True)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            stream.write(content)
            stream.flush()
            os.fchmod(stream.fileno(), 0o600)
        os.replace(temporary, path)
        os.chmod(path, 0o600)
    finally:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass


def validate_url(value: str, host: str, port: int) -> None:
    try:
        parsed = urlsplit(value)
        parsed_port = parsed.port
    except ValueError:
        fail("invalid media broker endpoint")
    if (
        parsed.scheme != "http"
        or parsed.hostname != host
        or parsed_port != port
        or parsed.path != "/mcp"
        or parsed.query
        or parsed.fragment
        or parsed.username
        or parsed.password
    ):
        fail("invalid media broker endpoint")


def main() -> None:
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("--config", required=True, type=pathlib.Path)
    parser.add_argument("--env", required=True, type=pathlib.Path)
    parser.add_argument("--marker", required=True, type=pathlib.Path)
    parser.add_argument("--url", required=True)
    parser.add_argument("--allowed-host", required=True)
    parser.add_argument("--allowed-port", required=True, type=int)
    parser.add_argument("--mode", choices=("enabled", "disabled"), required=True)
    parser.add_argument("--takeover", choices=("true", "false"), default="false")
    args = parser.parse_args()
    enabled = args.mode == "enabled"
    takeover = args.takeover == "true"
    if enabled:
        validate_url(args.url, args.allowed_host, args.allowed_port)
    owned = is_owned(args.marker)
    if not enabled and not owned:
        # Disabled is a true no-op on a fresh or unowned Hermes installation,
        # but an existing malformed file still fails closed below.
        if args.config.exists():
            read_yaml(args.config)
        return
    token = os.environ.get(TOKEN_KEY, "")
    if enabled and not token:
        fail("media broker token is required when enabled")
    updated, yaml_changed = reconcile_yaml(args.config, enabled, args.url, takeover, owned)
    env_content, env_changed = reconcile_env(args.env, enabled, token, owned)
    if yaml_changed:
        atomic_write(args.config, yaml.safe_dump(updated, sort_keys=False))
    if env_changed:
        atomic_write(args.env, env_content)
    if enabled:
        if args.config.exists():
            os.chmod(args.config, 0o600)
        if args.env.exists():
            os.chmod(args.env, 0o600)
        if not owned:
            atomic_write(args.marker, MARKER)
    elif owned:
        try:
            args.marker.unlink()
        except FileNotFoundError:
            pass


if __name__ == "__main__":
    main()

