            return None
        parts = path.split("/")
        if len(parts) > 1 and API_VERSION.fullmatch(parts[1]):
            parts.pop(1)
            path = "/" + "/".join(parts[1:])
        if path == "/_ping":
            return ("ping", parsed.query)
        if path == "/version":
            return ("version", parsed.query)
        if path == "/containers/json":
            return ("list", parsed.query)
