    def _query_for_list(self, query: str) -> str | None:
        if not query:
            return ""
        if "%" in query or "+" in query or "&" in query or "=" not in query:
            return None
        key, value = query.split("=", 1)
        if key != "all" or value not in ("0", "1"):
            return None
        return "?all=" + value

    def _serve(self) -> None:
        route = self._route()
